package com.tifloacosta.nativeprototype

/** Settings details: interface text only, never editorial or user content. */
internal object NativeSettingsDetailStrings {
    private val keys = listOf("directContact", "email", "myBook", "bookDescription", "print", "close", "account", "storage", "notifications", "sharing", "fullPolicy", "accessibilityNote")
    private val catalog = mapOf(
        "es" to listOf("Contacto directo", "Enviar correo", "Mi libro", "Libro de Tony Acosta, disponible en papel y Kindle.", "Edición en papel", "Cerrar", "Puedes utilizar TifloAcosta sin crear una cuenta.", "Los documentos, las posiciones de lectura y las marcas permanecen en el almacenamiento privado de la aplicación.", "Las notificaciones son opcionales. Puedes cambiar los permisos desde los ajustes de Android.", "Tú decides cuándo compartir un documento o enlace con otras aplicaciones.", "Política de privacidad completa", "Los controles están identificados para TalkBack. Puedes ampliar el texto en Configuración y ajustar las voces dentro de TifloLector."),
        "en" to listOf("Direct contact", "Send email", "My book", "Tony Acosta's book, available in print and Kindle.", "Print edition", "Close", "You can use TifloAcosta without creating an account.", "Imported documents, reading progress and bookmarks remain in the app's private storage.", "Notifications are optional. You can change Android permissions in system settings.", "You control when a document or link is shared with another app.", "Full privacy policy", "Controls are labeled for TalkBack. You can enlarge text in Settings and adjust voices inside TifloLector."),
        "pt" to listOf("Contacto direto", "Enviar correio", "O meu livro", "Livro de Tony Acosta, disponível em papel e Kindle.", "Edição em papel", "Fechar", "Podes usar o TifloAcosta sem criar conta.", "Os documentos importados, as posições de leitura e os marcadores ficam no armazenamento privado da aplicação.", "As notificações são opcionais. Podes alterar as permissões nas definições do Android.", "Tu decides quando partilhar um documento ou uma ligação com outra aplicação.", "Política de privacidade completa", "Os controlos estão identificados para o TalkBack. Podes aumentar o texto nas Definições e ajustar as vozes no TifloLector."),
        "fr" to listOf("Contact direct", "Envoyer un courriel", "Mon livre", "Livre de Tony Acosta, disponible en version papier et Kindle.", "Édition papier", "Fermer", "Tu peux utiliser TifloAcosta sans créer de compte.", "Les documents importés, positions de lecture et signets restent dans l’espace privé de l’application.", "Les notifications sont facultatives. Tu peux modifier les autorisations dans les paramètres Android.", "Tu décides quand partager un document ou un lien avec une autre application.", "Politique de confidentialité complète", "Les commandes sont identifiées pour TalkBack. Tu peux agrandir le texte dans les Paramètres et régler les voix dans TifloLector."),
        "it" to listOf("Contatto diretto", "Invia email", "Il mio libro", "Libro di Tony Acosta, disponibile in formato cartaceo e Kindle.", "Edizione cartacea", "Chiudi", "Puoi usare TifloAcosta senza creare un account.", "I documenti importati, le posizioni di lettura e i segnalibri restano nello spazio privato dell’app.", "Le notifiche sono facoltative. Puoi modificare le autorizzazioni nelle impostazioni Android.", "Decidi tu quando condividere un documento o un collegamento con un’altra app.", "Informativa privacy completa", "I controlli sono etichettati per TalkBack. Puoi ingrandire il testo nelle Impostazioni e regolare le voci in TifloLector."),
        "de" to listOf("Direktkontakt", "E-Mail senden", "Mein Buch", "Buch von Tony Acosta, als Druckausgabe und für Kindle erhältlich.", "Druckausgabe", "Schließen", "Du kannst TifloAcosta ohne Konto nutzen.", "Importierte Dokumente, Lesepositionen und Lesezeichen bleiben im privaten Speicher der App.", "Benachrichtigungen sind optional. Android-Berechtigungen lassen sich in den Systemeinstellungen ändern.", "Du entscheidest, wann du ein Dokument oder einen Link mit anderen Apps teilst.", "Vollständige Datenschutzerklärung", "Die Bedienelemente sind für TalkBack beschriftet. Du kannst in den Einstellungen Text vergrößern und in TifloLector Stimmen anpassen.")
    )
    fun get(language: String, key: String): String {
        val index = keys.indexOf(key)
        if (index < 0) return key
        return (catalog[language] ?: catalog.getValue("es"))[index]
    }
}
